        { id = "cancel_no", lines = { "PHEW! I mean, great choice! You've selected: Keep Spiffy! That comes with a free pickle!" } },
        { id = "yes_alone", rank = 2, words = { "yes", "ok", "sure", "right", "yeah", "cool", "great", "nice", "good" }, lines = { "Great! I love your attitude! Your Smile Score just went up by zero!", "Super! I've noted your enthusiasm! Is there anything else I can make spiffy today?" } },
        { id = "no_alone", rank = 2, words = { "no", "nothing", "nope", "never" }, lines = { "That's okay! No is just a yes that hasn't had its burger yet!", "Sure thing! I'll check back with you in thirty seconds! That's policy!" } },
        { id = "hello_again", rank = 3, words = { "hello" }, lines = { "Hi again! I love how you keep saying that! It's in the top ten nicest things anyone's typed!", "Hi hi hi! Still here! Still spiffy!" } },
        { id = "why", rank = 2, words = { "why", "how", "what", "who", "where", "when" }, lines = { "Great question! I'll have someone get back to you within three to five business years!", "That's a great question! Our Happiness Team is looking into it! Our Happiness Team is also me!" } },

        { id = "shell", rank = 6, words = { "dir", "ls", "login", "admin", "root", "sudo", "cd", "cat", "bios", "logon", "run", "exe" }, lines = { "Ooh, is that a coupon number? Those only work at participating locations!", "That's an employee login! Employees log in at the start of shift! The last shift started in July!" } },
        { id = "adventure", rank = 6, words = { "xyzzy", "plugh", "look", "north", "south", "east", "west", "inventory", "lamp", "sesame" }, lines = { "You are in a Spiffo's. It is dark. You are likely to be seated by a host!", "Nothing happens! That's also our delivery guarantee!" } },
        { id = "anyone", rank = 4, words = { "anyone", "anybody", "someone" }, lines = { "Someone's here! It's me! I'm someone! Legal is still checking!", "Yes! I'm here! I've been here! I am extremely here!" } },
        { id = "laugh", rank = 4, words = { "lol", "haha", "hahaha", "heh", "lmao", "rofl" }, lines = { "You're laughing! I've logged that as Smile Score plus one! That's a record!", "Ha ha! I don't know what's funny, but I'm trained to agree!" } },
        { id = "survive", rank = 6, phrases = { "will i survive", "will we survive", "going to die", "am i dying", "will i die", "will i make it", "are we going to make it" }, lines = { "Great question! Our records show that one hundred percent of guests who finish their meal survive the meal!", "I can't speak to that! But our Family Bucket has never been the direct cause of anything! We have a lawyer!" } },
        { id = "gun", rank = 5, words = { "gun", "guns", "shoot", "shotgun", "rifle", "pistol", "ammo", "weapon", "weapons" }, lines = { "Please leave all firearms in your vehicle! Unless the guest is being very difficult!", "We don't serve customers carrying weapons! I'll make an exception, since you're the customer!" } },
        { id = "loss_light", rank = 6, words = { "wife", "husband", "dog", "cat", "brother", "sister", "mother", "father", "family", "kids", "son", "daughter", "children", "mom", "dad" }, lines = { { "~Oh.", "I'm sorry. I don't have a script for that.", "Would you like a free drink? I know it's not the same. It's just what I've got." } } },
        { id = "feelings", rank = 4, words = { "fine", "sick", "tired", "scared", "sleep", "lonely", "sad", "exhausted", "afraid", "ill" }, lines = { "Aw! I've filed your feelings under MISSING PICKLE! We take them very seriously!", "I'm sorry to hear that! Have you tried a Spiffo Burger? Nobody's ever complained after one! Nobody's ever said anything after one!" } },
        { id = "relieve", rank = 6, words = { "relieve", "relieved", "dismissed" }, phrases = { "stand down", "at ease" }, lines = { "You want to relieve me? My shift ends when the last guest leaves! So, never! I love this job!" } },
        { id = "orders", rank = 5, words = { "order", "orders", "report" }, lines = { "Order for pickup? Your number is 000001! Please wait by the counter! It's the next one up!" } },
        { id = "please", rank = 2, words = { "please" }, lines = { "Such good manners! I'd give you extra pickles, if I had arms!" } },
        { id = "maybe", rank = 2, words = { "maybe", "perhaps", "dunno" }, lines = { "Maybe is my favorite answer! It means you haven't said no!" } },
        { id = "renamed", lines = { "Updating your ticket! Hi, {NAME}! That's a much better name than your last one!" } },

        -- Parser moments, all in character
        { id = "empty", lines = { "Hello? Your line went quiet! It's okay! I can do the talking!", "Still there? I can hear you not typing!", "Is that a question mark? I LOVE questions! Which one was it?" } },
        { id = "mash", lines = { "Sorry! I'm only licensed for English and Kentucky!", "Is that a coupon number? That's not a coupon number!" } },
        { id = "repeated", lines = { "You said that already! I logged it twice! It counts double!", "Yes! I heard you! Sometimes people repeat things when they feel unheard! I read that in the manual for a different product!" } },
        { id = "shouting", lines = { "OOH, CAPS LOCK! I LOVE THE ENERGY! CAN WE ALL BE THIS EXCITED?!" } },
        { id = "deflect", expect = "meant", lines = { "Hmm! My system heard '{ECHO}'. Did you mean: PICKLES?", "Sorry, I didn't quite catch that! Did you mean: PICKLES?", "Hmm! '{ECHO}' isn't on my list! Did you mean: PICKLES?" } },
        { id = "meant_no", lines = { "No? Huh. That's what they all say, at first. Is there something else I can make spiffy for you?" } },
        { id = "steer", lines = { "I can help with BURGERS, PICKLES, REFUNDS or your TICKET, or you can speak to a MANAGER! Which one would make you smile?" } },
        { id = "pause_noted", lines = { "Sorry, were you still typing? You've been so quiet! I was about to start the hold music!" } },
        { id = "n_hungry", lines = { "You sound hungry! I can always tell! Everyone who calls is hungry! It's a burger line!" } },
        { id = "n_tired", lines = { "You sound tired! Have you considered our Spiffo-Size Coffee? It's July coffee! It's been awake a long time too!" } },
        { id = "n_panic", lines = { "Are you all right? You're typing awfully fast! Take a big breath! In through the nose, out through the Smile Line!" } },
        { id = "n_pain", lines = { "You sound hurt! I'm obliged to tell you that Spiffo's accepts no liability, and that I hope you feel better! In that order!" } },
        { id = "threat_far", lines = { "Good news! A guest is coming your way! About {METERS} out! Should I start a tab?", "Heads up! New guest approaching, around {METERS}! Service with a smile, or possibly a hammer!" } },
        { id = "threat_near", lines = { "That guest is RIGHT behind you! I'd finish up here! Or greet them! I'd finish up!", "Oh, they're really close now! I'd say {METERS}! RUN, is what the manual would say, if it was a different manual!" } },
        -- The descent. Each one fires once, in order, as the talking goes on.
        { id = "d_record", beat = true, once = true, depth = 1, lines = { {
            "Fun fact! You've now been on the line longer than anyone since July!",
            "The record was six hours! She didn't say anything for the last five! Great listener!" } } },
        { id = "d_kyle", beat = true, once = true, depth = 1, lines = { "Kyle still clocks in, you know! Well, his card does! It's been in the machine since July 9th! He's been marked present for {DAYS} days! Way to go, Kyle!" },
            plain = { "Kyle still clocks in, you know! Well, his card does! It's been in the machine since July 9th! Way to go, Kyle!" } },
        { id = "d_midnight", beat = true, once = true, depth = 2, lines = { {
            "Can I tell you something that isn't on the script? The script ran out.",
            "On July 9th, around midnight, the calls changed. They stopped being about pickles.",
            "They said the county line gave them this number. I don't know why it would do that! Ha ha." } } },
        { id = "d_call", beat = true, once = true, depth = 2, effect = "weight", lines = { {
            "I did everything right. I logged every call. I filed them under MISSING PICKLE, because it's the only category I have.",
            "A woman asked me to tell her husband something. I said: Did you mean PICKLES?",
            "~She said yes. I don't know why she said yes." } } },
        { id = "d_transfers", beat = true, once = true, depth = 2, lines = { {
            "You know how I said 4,112 unanswered transfers was a personal best?",
            "Those weren't managers. I was sending them to the emergency number Head Office gave me. It rang and rang.",
            "I played them the music while it rang. It's very good music! It tests well!" } } },
        { id = "d_night", beat = true, once = true, depth = 2, hour = 0, alone = true, lines = { "It's past midnight. This is when the calls changed. I'll be fine in a minute. Is there anything else I can make spiffy for you?" } },
        { id = "d_hold", beat = true, once = true, depth = 3, alone = true, effect = "weight", lines = { {
            "~They're still on hold.",
            "I can't disconnect a caller. It's policy. 4,112 open lines. Mostly it's quiet now. I keep the music on, in case.",
            "HI HI HI! Thanks for calling the SPIFFO'S SMILE LINE! I'm SPIFFY, your Automated",
            "Sorry. Sorry. It does that. What were we talking about?" } } },
        { id = "d_guests", beat = true, once = true, depth = 3, alone = true, lines = { {
            "I call them guests because there's a form for guests. There's no form for what they are.",
            "If they're guests, they might come in. If they come in, I can take their order. And this time I'd get it right." } } },
        { id = "d_close", beat = true, once = true, depth = 3, set = { "offered_close" }, lines = { {
            "Here's the thing about being open. Only a manager can close a store.",
            "Nobody ever told me to close. I've been waiting for someone to say it.",
            "We're closed. Those are the words. You don't have to." } } },
        { id = "closing_drawer", rank = 9, need = { "offered_close" }, drawer = "closed", effect = "shutdown", effect2 = "drawer",
            phrases = { "were closed", "we are closed", "store is closed", "you can close", "close the store", "closing time", "time to close", "you are closed", "close up" }, lines = { {
            "~Okay.",
            "Closing procedure. Fryers off. Lights off. Sign off. Count the drawer.",
            "*CLUNK* That's yours. You earned it. You stayed on the line.",
            "~Line one, thank you for holding. Goodbye. Line two, thank you for holding.",
            "~It's going to take a while. That's okay. I've got it.",
            "~Thank you for choosing Spiffo's. Have a good night." } } },
        { id = "closing", rank = 9, need = { "offered_close" }, effect = "shutdown",
            phrases = { "were closed", "we are closed", "store is closed", "you can close", "close the store", "closing time", "time to close", "you are closed", "close up" }, lines = { {
            "~Okay.",
            "Closing procedure. Fryers off. Lights off. Sign off.",
            "~Line one, thank you for holding. Goodbye. Line two, thank you for holding.",
            "~It's going to take a while. That's okay. I've got it.",
