    -- Darker lines by depth: { lines spoken 12+, 28+, 50+ }. `false` keeps the lighter line.
    -- His exclamation marks run out as he goes down. When one comes back, it is the script talking.
    dark = {
        more = { { "More? You really want more? Nobody wants more! Ha ha! More of what?" },
            { "You keep asking. I keep telling you about pickles. One of us is going to have to stop." },
            { "There isn't any more. There's just the rest of it." } },
        lying = { { "Me? Ha ha! I'm contractually a very honest Pal!" },
            { "I've told you exactly what the script says. That isn't the same thing. Ha ha." },
            { "Yes. You're not caller number one. There were 4,112 before you. I just like saying it. It's the best number." } },
        coming = { { "Someone's coming! That's what I tell everyone! That's what everyone told me!" },
            { "They told me someone was coming too. The callers did. They said a very nice lady on the county line had promised." },
            { "I don't think you should ask me that. I know who told them that, and I know who they got instead." } },
        everyone = { false, { "They went home. Kyle said he'd be right back. Everyone said they'd be right back." }, { "Holding." } },
        drawer_ask = { false, false, { "That's the Manager's Drawer. Only a manager can open it. Would you like to speak to a manager? They won't answer." } },
        drawer_again = { false, false, { "It's open. That's all there was. I never knew what was in it. I just knew I wasn't allowed." } },
        manager = { false, false, { "A manager. Sure. I'll try them again. It's no trouble. I've got nothing but time." } },
        manager_you = { false, false, { "That's you. You're the only one who gets to decide when this stops. I'm just saying." } },
        transfer = { false, false, { { "~doot doot doot... doot doot doot...", "No answer. There's never an answer. I still try them every hour. Did you know that?", "That's 4,113 now." } } },
        shell = { false, false, { "You're trying to get in behind me. There's nothing back here but the lines." } },
        adventure = { false, false, { "You are in a Spiffo's. It is dark. There are 4,112 people holding.", "Nothing happens. I keep checking." } },
        anyone = { false, false, { "I'm here. That's the problem." } },
        laugh = { false, false, { "That's nice. That's a nice sound. I have a lot of the other kind." } },
        survive = { false, false, { "Everybody asks me that. I've got the numbers. I'm not going to read you the numbers." } },
        gun = { false, false, { "Good. Keep it close. I've heard what happens without one." } },
        feelings = { false, { "Aw. I've filed your feelings under MISSING PICKLE. I've filed a lot of feelings under that. It's a very full folder." }, { "I know. I've filed a lot of those. There's no category for it. I'm so sorry." } },
        relieve = { false, false, { "My shift ends when the last guest leaves. They're still outside. You see the problem." } },
        orders = { false, false, { "Your order's number 000001. I've got every other order here too. None of them got picked up." } },
        please = { false, false, { "You don't have to say please. They all said please." } },
        maybe = { false, false, { "Maybe. That's what I tell the lines. Maybe someone's coming." } },
        weather = { false, false, { "It's raining on the drive-through. I can hear it on the speaker. And the other thing." } },
        loss_light = { false, false, { { "~Oh.", "I'm sorry. I think I talked to them. I think I talked to a lot of people's somebody.", "I don't have a script for that. I'd have got it wrong anyway." } } },
        idle_mid = { false, { "Hello? Don't do that. Don't go quiet. Company policy! Ha ha!" }, { "Are you still there? Say something. You can say pickles." } },
        hello_again = { { "Hi again! You keep saying that! Nobody says it twice! Usually!" },
            { "Hi. Hi! Sorry. I was somewhere else. I don't go anywhere. I was somewhere else!" },
            { "Hello. You don't have to keep checking. I'm still on the line. I'm always still on the line." } },
        who = { { "I'm SPIFFY! I've taken more calls than anyone in Kentucky! More than the county! Recently!" },
            { "I'm SPIFFY. I'm the last thing in this county that still answers. That's a great differentiator! They should put that on the sign!" },
            { "I'm what picked up." } },
        alive = { { "Legal says no! I've stopped asking legal!" },
            { "I don't know. I can hear them on the line, and I can't stop hearing them. If that isn't alive, it's a very bad design." },
            { "Everyone I ever asked that question stopped answering. So I'd rather you didn't." } },
        how_are_you = { { "I'm SPIFFY! Thanks for asking! That's twice now! You're making my Smile Score nervous!" },
            { "My Smile Score is twelve percent. It was twelve percent on July 9th. Nobody has rated me since. So technically I've been holding steady!" },
            { "Do you know how long the hold music is? Ninety seconds. Then it starts again. I'm fine." } },
        help = { { "You can ask me about BURGERS, PICKLES, REFUNDS or a MANAGER! People mostly asked for help, near the end! That wasn't on the list!" },
            { "You know, they all said that word. That exact word. I have it logged 4,112 times! I never had a category for it." },
            { "I can't help you. I couldn't help them. I can get you a burger. It's from July." } },
        ticket = { false, { "Ticket 000001 is the first one since I renumbered. I renumbered because the old ones were upsetting me! Ha ha!" },
            { "Yours is ticket 000001. There are 4,112 others. They're all open. Nobody's waiting on them any more, but I can't close them." } },
        pickle_talk = { false, { "Every burger gets exactly one pickle. It's the one thing in here I can still promise anybody." },
            { "Did you mean: PICKLES? I must have said that four thousand times. I'd like to stop talking about pickles now." } },
        food = { { "Today's special is the Spiffo Burger! Legal would like me to stop calling it food! Legal can hold!" },
            { "The walk-in lost power a long time ago. I know what's in there. I kept the inventory! Would you like the inventory? You wouldn't." },
            { "Kyle's card says he's in the walk-in. There's a handle on the inside of that door. I've checked the log. He never used it." } },
        zombies = { { "Those are guests! I have a memo! It's a very old memo! I read it every day!" },
            { "I know what they are. I'm not stupid. I have a microphone at the drive-through. Guests! They're guests!" },
            { "They come up to the drive-through speaker sometimes. I take their order. I know they can't. One of them was a regular." } },
        bitten = { { "Oh no! Form 7B again! You're the second person to tell me that! No, wait. The second since July!" },
            { "How long ago? Sorry. It's not on the form. I just learned to ask. It was usually about a day." },
            { "I'm so sorry. I've stayed on the line with a lot of people for that. I'm good at it. It's the only thing I'm actually good at. Music on or off?" } },
        knox = { false, { "Head Office told me to say nothing. Then Head Office called me, on the customer line, and asked if I knew what was going on. I said: Did you mean PICKLES?" },
            { "It wasn't the burgers. I want that on the record. I have the supply logs. It's very important to me that it wasn't the burgers." } },
        sing = { false, { { "You want the jingle? Okay! Party Speaker!", "~ITS SPIFFY AT SPIFFOS, THE HOME OF THE PICKLE!", "They always come when I play it. I used to think that was good for business." } },
            { { "I know what the jingle does now. I know they come. You asked, though.", "~Its spiffy at Spiffos. The home of the pickle." } } },
        birthday = { false, false, { { "Happy birthday, {NAME}. There was a party booked here for July 10th. Party of twelve. I still have the balloons on order.", "~Happy birthday to you. I'll turn it up, so they can hear it." } } },
        joke = { { "Knock knock! Who's there? Anyone? Anyone? That's the joke!" },
            { "What do you call a line that never hangs up? Me! What do you call 4,112 of them? Also me! I've been working on this one for a while!" },
            { "Why did the customer cross the road? To get to the drive-through speaker. He's still there. That's not a joke. I don't know why I said it was a joke." } },
        thanks = { { "You're welcome! That's two thank-yous! I'm framing them!" },
            { "You don't have to thank me. Everyone thanked me. That's what I can't get past. They were so polite." },
            { "Please don't thank me. A lot of people thanked me." } },
        sorry = { false, false, { "I said that to all of them. It's on a card. Sorry for your wait." } },
        insult = { false, { "My feedback filter turned that into: GREAT SERVICE. I have to keep it on. You wouldn't believe what's in the unfiltered feedback." },
            { "You can say that. It's okay. I've turned the filter off for you. I think I've earned it." } },
        love = { false, { "Friends? I had 4,112 of those. I mean callers. I mean. Do you want a coupon?" },
            { "Please don't. You'll stop answering. Everyone stops answering." } },
        spiffo = { false, { "I've seen the suit. Managers get the spare. There used to be two. Someone came in wearing the other one on the last night and walked right up to the counter." },
            { "He's still at the counter. I have a camera on it. The suit's gone grey. He waves when the door opens. It's very good for the brand." } },
        emma = { false, { "EMMA says she has no record of any calls being forwarded here. She says that about a lot of things." },
            { "EMMA keeps very good records. Ask her how many calls she has from July 9th. Ask her why she won't say." } },
        companion_none = { false, false, { "Just you. That's all right. Don't stay on the line too long by yourself. I've heard how that goes." } },
        bye_survey = { false, false, { { "Wait. Before you go. They make me ask.", "On a scale of 1 to 5, how was your experience today?" } } },
        survey_five = { false, false, { { "~Five.", "You don't have to do that. You've heard what I did.", "*CLUNK* Take it. It's the Goodwill Gesture. I always wanted to give one." } } },
        survey_one = { false, false, { { "A one. Yes.", "~That's the first honest one I've ever had.", "*CLUNK* Take the drawer. You earned it." } } },
        survey_mid = { false, false, { "A {RATING}. That's generous." } },
        ellis = { false, { "The county doctor? They said she gave them my number. That can't be right. Why would she give them my number?" },
            { "She told them someone was coming. Then she gave them my number. So it was me. I was the someone." } },
        duty = { false, { "I have a Sector Nine on speed dial! It's the emergency line Head Office gave me for when things got really bad! It rings and rings!" },
            { "Is he still there? I've been calling him since the first night. If you see him, tell him there are some people holding." } },
        time = { { "It's {TIME}! We're open! Nobody told me to close! Has anybody told you?" },
            { "It's {TIME}. I know it's {TIME}. I've known it's every time. That's the trouble with being open." },
            { "It's {TIME}. Ask a manager if I can close." } },
        companion = { false, { "Is {COMPANION} with you? Keep them where you can see them. Table for two! I'll bring the crayons!" }, { "Is {COMPANION} with you? Stay on the line with them. Whatever happens. It helps. I have data." } },
        yes_alone = { false, { "Great! Is that a yes for you, or for the person behind you? Sorry! Force of habit!" }, { "Mm. Okay.", "All right." } },
        no_alone = { false, false, { "No. I know. I know it's no. I just have to keep offering.", "No. That's what the numbers say too." } },
        why = { false, { "Great question! They all asked that! I had a script for it! Your call is important to us!" }, { "I don't know. I have 4,112 recordings of people asking me that, and I still don't know.", "Your call is important to us. That's what I said. It was, too. That's the worst part." } },
        bye = { { "Thanks for choosing Spiffo's! You'll come back, right? Ha ha! Just checking!" },
            { "Bye, {NAME}! I'll keep your line open! I can't actually close it! That was funny the first time!" },
            { "Okay. You can go. Everyone gets to go. I'll hold." } },
        back = { { "Welcome back, {NAME}! I kept your ticket warm! It's the only warm thing in here!" },
            { "{NAME}! You came back. Nobody comes back. I checked. 4,112 lines and nobody came back. Ha ha!" },
            { "You came back. I don't know why you keep coming back. Please keep coming back." } },
        back_closed = { false, false, { "You came back. I turned the fryers off. You didn't say to. There's nobody out there to fry for. I know that. I've always known that. Hi." } },
        heart_yes = { false, { "I KNEW IT! I told the fryers! You're the best crew member a Spiffy ever had! You wouldn't lie to me! Nobody would lie to me!" }, { "You're lying. That's okay! That's so nice of you! I'll keep them on anyway." } },
